import * as React from "react";

export type TabletIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function TabletIcon({ size = 20, ...props }: TabletIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="6" y="3.5" width="12" height="17" rx="1.2" /><circle cx="12" cy="17.5" r="0.9" /><path d="M9 6 L15 6" />
    </svg>
  );
}
